using System.Collections.Generic;
using System.Linq;
namespace PriceOfBread.SimCore;

/// <summary>
/// 全体のチューニング係数（§9-A/§9-D）。財ごとのパラメータは Good／Producer 側が持つ。
/// 値は最終的に §8 の sweep で導出する（ここは段0/1 が健全に動く暫定値）。
///
/// ★★★**判定順序（作者裁定 2026-08-01・最上位。08_バランス調整方針 §1 の4段順序を差し替える）**：
///   **ゲームが破綻しない ＞ 正しい挙動（リアリティ・納得感）＞ バランス（史実忠実度の帯）**
/// ⚠**「帯が悪くなった」というだけで機構を差し戻さない。** 差し戻すのは破綻（クラッシュ・保存則違反・デッドロック・テスト赤）か、
///   挙動が明らかに不自然になる場合に限る。★より正しい機構で帯が悪化したときは**採用したうえで、悪化した数値と
///   「較正で取り戻す対象である」ことを、この行内コメントと docs の両方に必ず書く**。
/// ⚠**記録を欠いた採用は認められない**——帯の劣化が「意図した負債」なのか「未検出の不具合」なのかが後から区別できなくなるため。
/// </summary>
public sealed class Coefficients
{
    // --- 市場（§9-A）---
    public double PriceAdjustSpeed = 0.13;   // 価格の積分項：在庫ギャップ駆動（§9-A 仕組み1）。0.08→0.13＝価格の変動をより顕著に（ユーザー要望）
    public double FlowAdjustSpeed = 0.48;    // 価格の比例項：需給差駆動＝振動の減衰（設計判断A）。需給差を**自然有界な (D−S)/(D+S)∈[−1,1]** で測る（旧 (D−S)/S は S→0 で∞＝FlowCap で蓋が必要だった）。平常域は (D−S)/(D+S)≈x/2 なので旧0.24の2倍=0.48でゲインを温存し、崩壊時は±1で連続有界（蓋不要）
    public double PriceElasticity = 0.5;     // 段B：日次価格探索の需給の価格弾力性。実効需要 eD=D×(rp/P)^ε・実効供給 eS=S×(P/rp)^ε ＝価格が参照から離れると需要減・供給増で**押し戻す復元力**。均衡 P*=rp×(D/S)^(1/2ε) は有限＝クランプが張り付かず外側の安全網へ降格。P=rp(平衡)では eD=D,eS=S＝段Aと同一なので平常較正への影響は小。0=段A（弾力性なし）
    // 加速度的な価格是正（要望）：平衡(100%)近くは緩やか、端ほど急峻。倍率＝Center＋(Edge−Center)×ndist^Power。
    // ndist＝|ln(価格/参照価格)|÷ln(1/床係数)＝床5%・天井2000%で1.0（対称）。50%/150%は今までと同等以下、5%/2000%は直ちに是正。
    public double PriceAmpLnScale = 2.9957;  // amp曲線の端の対数距離（=ln20）。旧は床係数に連動していたが、安全網クランプ幅とは別概念なので分離（クランプを広げてもamp曲線＝是正の強さは不変）。既定はln(20)で従来同値
    public double PriceAmpCenter = 0.7;      // 100%付近の調整倍率（<1＝張り付かない範囲は今までより静か）
    public double PriceAmpEdge = 8.0;        // 床5%/天井2000%での調整倍率（≫1＝極端な乖離は直ちに是正）
    public double PriceAmpPower = 3.0;       // 増幅の凸度（高いほど中間は平坦・端だけ急峻＝加速度的）
    public double SupplyAdjustSpeed = 0.15;  // 供給能力調整の速さ（§9-A 仕組み4）。0.12→0.15＝供給が価格に速く追従しコブウェブ振動を減らす（価格二極化の緩和）。0.18は工業最先進の英を強くしすぎ常勝化したため0.15に抑制
    // ※適応的期待（供給を期待価格EMAに反応）を試したが二極化が悪化（49→40%）＝二極化はコブウェブ振動でなく供給能力不足（実需要に届かない）が主因と判明・撤回
    public double SupplySlope = 0.5;         // 供給曲線の傾き（オプションB）：価格が mc×(1+これ) で能力上限
    // ★再点火発注の決済（点火2026-08-01・作者指摘「実装の形としては正だが、実装方法としてスマートでない。同等かよりリアリティのある挙動を確保できるなら差し替えて」）。
    // 0＝旧（現物だけが動き、代金も所得も発生しない）／1＝止まった工場の持ち主が貯蓄から払い、売った側が受け取る。
    // ⚠**発注量・配給・物量の消費は1つも変えない**＝作者が意図した「上位工場を先に建ててから下流を整備する」プレイの余地はそのまま残る。
    public double ReignitionOrderSettles = 1.0;
    public double ReignitionDemandFrac = 0.03;  // 入力需要の再点火トリクル＝採算が合えば「作りたい量」のこの割合を最低需要に（産出の床に代わるデッドロック防止。死んだ工場も需要を残し価格で蘇生＝無から有なし）
    public double PriceFactorMin = 0.4;      // 価格弾力の下クランプ
    public double PriceFactorMax = 1.4;      // 価格弾力の上クランプ
    // 交差弾力性（B-2）：主食内の相対価格で需要を再配分（パン高騰→芋へ＝飢饉の核心）。基準＝主食の(価格/参照価格)の幾何平均、平均の財は不変、安い財ほど需要↑。0で無効。
    public double CrossElasticity = 0.6;     // 主食間の代替の強さ（相対価格の指数）。上限/下限は PriceFactorMin/Max を流用
    // 価格の床/天井＝参照価格×これ。段B（弾力性均衡）で**非load-bearingの安全網**に降格：弾力性の復元力が価格を帯のはるか内側で抑えるため通常は張り付かない
    // （検証：0.002/500 まで広げても119＋33/33/33が緑＝旧コメントの「撤去で10件破綻」を解消）。残す理由は真の供給0＝死財（D>0,S=0）の病的∞発散を防ぐ最後の砦のみ。
    public double PriceFloorFactor = 0.01;    // 暴落の底（安全網）
    public double PriceCeilFactor = 100.0;    // 暴騰の天井（安全網）
    public double SoftBandSharpness = 8.0;    // 価格安全網(SoftBand)の対数空間飽和の鋭さ（→∞でハードクランプ。旧 MarketFlow関数内 const 8.0 を係数化＝sweep対象）
    // ※FlowCap は撤廃（段A）：需給差を (D−S)/(D+S) で測れば本質的に[−1,1]有界＝S→0 の D/ε 爆発が原理的に起きず、絶対上限の蓋が不要になった
    // 在庫目標は処理量（総需要）に比例させる＝凍結値だと高処理量財の在庫項が常に大負になり価格が床へ叩き落とされる（価格シグナルの破れ）
    public double TargetStockBuffer = 1.0;   // 在庫目標 ＝ 総需要 × これ（≒保有したい在庫＝数期分の需要）。⚠DesiredInventoryCover と対＝セットでのみ動かす（下記参照）
    // === テーマH（産業組織・固定資本・住宅）===
    public double InventoryAdjustGain = 0.1;     // メッツラー在庫循環＝在庫についての期待。05-B1（2026-07-29）点火：期待導入の最初の一歩（増幅側＝恐慌を増やす方向・05 §5）。0で旧恒等
    public double DesiredInventoryCover = 1.0;   // 望ましい在庫＝これ×LastDemand（TargetStockBufferと一致＝定常でギャップ0）。⚠TargetStockBuffer と対＝一致しないと定常でギャップが残る。片方だけ動かさない（GridReplaceRate/GridDecayRateと同型）
    public double TargetStockFloor = 1.0;    // 在庫目標の下限（需要≈0でのゼロ除算回避）＝**「量として意味を持たない」の既存の物差し**（下の幻の生産のスナップもこの実用スケールを流用する）
    // ★墓標（2026-08-22・需要と供給の組み換え＝点火と削除）：労働配分の重みは「需要量×Scale」から「準レント×単位能力×Scale」＋配分信念EMAへ**無条件**に切替（EconomyStep の prodW 注記）。
    //   LaborRentWeight（構造スイッチ）・CrowdRentExpectation（混雑予期＝効果−2.4回・赤1件）・LaborFloorMix（均等床0.15＝準レント下では不要）・ExportDemandWeight（0.25の別建て加算＝価格に輸出が載るので次元不整合）は削除。
    //   測定＝準レント＋信念EMA＋床撤去＝硬性ゲート全緑・405緑・savetest 0.0E+000。大国8の1人あたり実質GDP＝エピソード7.1/試合・最大DD51%（基線2.8/31%・裸8.1/53.5%）。
    /* ★貿易の数量則書き換え（2026-08-22・docs/202608/20260822_貿易数量則の書き換え_設計_部分完了.md）。用量反応で「式の形が律速」を確定した後の段階実装。
       S1 暦＝TradeMonthlyClearing：国際清算を四半期1回→月次（MonthSettle の後）。量の式が月次規模を読むのに清算が四半期＝単位混在の是正（正しさの修正＝栓ではない）。
         0＝追加呼び出しゼロ＝ビット恒等。読み手は ClearingsPerYear / MonthsPerClearing で年換算・月割を揃える（×4.0 の直書きを残さない）。
       S3 価格法則＝PriceLawSeesExports：MarketFlow の flow 項の需要側に LastExport を足す。現行は輸入が在庫と供給の**両方**に載るのに輸出は在庫にしか載らない
         （BilateralMarket:460-461 と MarketFlow:27）＝輸出州の産出>需要を「過剰供給」と読み価格が崩れ→profitFactor（地元価格）が産出を絞る→輸出余剰が消える
         ＝**輸出する州ほど罰される非対称**（用量反応×100腕が2.91%で飽和した正体の有力候補＝天井でなくこの均衡）。0＝旧式を逐語に通る＝ビット恒等。
       どちらも 0/1 の構造スイッチ（中間値に意味なし＝運用禁止）。 */
    public double TradeMonthlyClearing = 1.0;   // ★点火2026-08-30（貿易数量則ラウンド・batch10段階測定→フルスタック採用）
    public double TradeLedgerFix = 1.0;     // S2台帳衛生（案E・2026-08-30）：人口の主食純輸入をゼロ化前の前清算値（Market.PrevImport/Export）で読む。0＝旧（常に0を見る＝発火不能）＝厳密恒等
    // 【墓標2026-09-26・旗の焼き込み（econ-15・x-01・0-3）】TradeArbitrageClearing（S4主フラグ・点火2026-08-30＝世界貿易/GDP 0.5%→42〜66%）と TradeCapacityHard（S4-1＝容量を同期制約に）
    //   ＝BilateralMarket は水準式の裁定清算と同期容量制約だけになった。旧経路（定数速度×自州規模）と、その専用の係数 TradeSpeed・TradeArbitrageMax・TradeBuyerScaleMult・TradeSellerFlowMult も削除
    // ★価格振動の根①（作者観察2026-09-07「硫黄が400%と34%で往復」・4レンズ→反証で確定）：日次価格則の供給項が LastProduced+LastImport だけで
    //   **倉庫の在庫を数えない**＝輸入の無い月は在庫が満杯でも需給差 flow が+1へ飽和し、参照価格からの距離で強くなる増幅項（PriceAmpEdge）が押し上げを
    //   加速する（観測点＝参照の8倍で月×6.4・端では×92）。1＝supply に m.Stock を足す（TargetStockBuffer=1.0＝在庫は既に「1ヶ月分の需要」の単位＝次元が合う）。
    //   在庫が需要を覆う州の価格は下がり、世界のどこにも無いときだけ上がり続ける。0＝旧式＝厳密恒等。単独腕 pricestock で計測。
    // ⚠2026-09-08 点火→**即日差し戻し**：帯は良くなった（exact45→48・near77→80・◎8→14）が、機構の番人が3件赤になった
    //   ＝助走で建材の需要が消える（機械の建設需要が61カ国中2カ国のみ生存）／自動拡張を止めた時にRGOの産出が痩せる（42434 vs 53334）／好況で信用が拡大しない。
    //   根＝**次元の取り違え**。LastProduced と LastImport は**フロー**（今月の量）だが m.Stock は**ストック**（積み上がった量）で、
    //   数か月分の在庫を抱えた市場では供給が過大に見え、価格が落ち、限界的な生産者が採算割れ（price<=mc）で止まる。
    //   直した形＝作者裁定 2026-09-08「備蓄がある限り、それは生産できているものとみなす」＝supply = max(流入, min(流入+在庫, 需要))。
    //   上限が需要なので在庫の過剰は需給差へ入らない（過剰の下押しは上の在庫ギャップ項の仕事＝二重計上を避ける）。
