    // ==== 海ノード吸着の是正 2026-08-16（docs/202608/20260816_海ノード吸着の是正_完了.md・実装時は休眠＝既定0で厳密ビット恒等／★点火梯子で0.5へ点火済み・live）====
    // 診断＝mapedges。SeaGraph.StitchCrossesLand は「**出港の一歩目（連続する陸）は数えない**」規則で、
    //   港が水際の町である以上、格子（Landmask＝海岸線を1マス内側へ収縮）の上では港自身が陸のマスに乗るための免除。
    //   ⚠その免除に**距離の上限が無かった**＝「線の全部が出港の一歩目」（一度も水に出ない線）まで合格する。
    //   実測（mapedges・OFF）：トリエステ(45.65,13.77)は最寄りのアドリア海北(179km)がイストリア半島で棄却され、
    //   **1,045km先のバルト南西(55.0,14.0)へ吸着**（陸上880km＝中欧を縦断する線が地図に描かれていた）。
    //   接ぎ木は SeaDistanceKm にそのまま加算され、海盆も採用ノードから継ぐので**表示だけの問題ではない**：
    //   トリエステ→ヴェネツィア 9,960km（実際150km＝×66）・トリエステの SeaBasin が Mediterranean でなく Baltic。
    //   同型は港州92件中21件（ハノイ1,036km・バンコク837・カナダ595・ブーシェフル476・ケルン352・グラスゴー143 ほか）。
    // 形＝免除に予算を持たせる：**その地点が水に出るまでの実測距離**（陸マスクの最寄り海マスまで＝トリエステで約5km、
    //   ケルンで78km、ハノイで52km＝mapedges の「港州から海までの距離」列と同じ量）× これ、を超えた先の陸は横断とみなす。
    //   ⚠固定kmのマジックナンバーを置かない（作者の流儀「固定値でなく既存の較正済み量に絡める」）＝**規模中立**＝
    //   河口や内海の港（水まで遠い町）の免除は自動的に長く、水際の港（トリエステ）の免除は自動的に短い。
    //   1.0＝「実測の出港距離ちょうどまで免除」＝物理的に必要な分だけ。免除の下限は格子1マス（11.1km）＝
    //   Landmask が海岸線を1マス内側へ収縮させてあるぶんの不確かさ（新しい数値ではなく格子の粗さの補正）。
    // ⚠1つも通らなければ**素の最寄りへ退避**する既存の規則がそのまま受ける＝トリエステはアドリア海北(179km)に落ち着く
    //   ＝「正しい海に出る」。退避が効くことは SeaGraphTests / SeaStitchBudgetTests が固定する。
    // ⚠海路距離が動く＝**較正非中立**（貿易/GDP・領土・列強の帯が動く）。点火A/Bは POB_COEF="SeaStitchLeadBudgetMult=1"
    //   で親がバッチ測定済み＝0.5を採用（1.0は地図の線が最少だが帯は0.5が上）。0＝旧規則（無制限免除）とビット恒等＝新しい実測（陸マスクの走査）は1回も走らない。
    public double SeaStitchLeadBudgetMult = 0.5;   // 【点火0.5・2026-08-16 点火梯子＝単独 exact43.3＝全16腕で最良／合成comp4で near77.4・人口28.6。1.0は地図の線は最少だが帯は0.5が上。合成comp4（12本＋海0.5）で exact41.6/near77.4/法63.2/貿易0.66・硬性緑】

    // 【墓標2026-09-26（棚卸し dorm-49）】エンジンの中の測定専用の腕2本を削除した：PopBudgetRelax（POP の予算の蓋を外す反実仮想＝保存則を破る）と
    //   TradeScaleUsesDesired（旧経路の交易の規模を予算の前の需要へ置き換える反実仮想・その素 Market.LastDesiredDemand を毎月全POP×全財で記帳していた）。
    //   反実仮想は Runner のプローブの中で世界を複製して行う（エンジンに誤って点火できる腕を置かない）

    // ==== 環境変数による係数の上書き（測定用・2026-08-12）====
    // なぜ要るか：A/B を**同一バイナリ・同一ソースハッシュ**で取るため。従来は既定値を書き換えて2回ビルドしていたが、
    // その間に他の編集が混ざると「挙動不変のはずの変更で軌道が動く」事故になる（設計doc「測定汚染」2026-07-28 と同じ罠）。
    //   使い方: POB_COEF="CrownlessCollapseKeepsRepublic=0;FactionOpportunism=0" bash measure.sh ...
    // 決定論：同じ環境変数なら同じ値＝再現する。未指定なら1件も触らない（＝厳密恒等）。
    // 名前を間違えたら**黙って無視せず例外**＝「掛けたつもりの実験が素通り」を構造で防ぐ（番人の空洞化対策）。
    private static readonly (string Name, double Value)[] Overrides = ParseOverrides();

    private static (string, double)[] ParseOverrides()
    {
        string? spec = System.Environment.GetEnvironmentVariable("POB_COEF");
        if (string.IsNullOrWhiteSpace(spec)) return [];
        var list = new List<(string, double)>();
        foreach (var part in spec.Split(';', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries))
        {
            int eq = part.IndexOf('=');
            if (eq <= 0) throw new ArgumentException($"POB_COEF の書式が不正: 「{part}」（名前=値 で書く）");
            string name = part[..eq].Trim();
            var field = typeof(Coefficients).GetField(name);
            if (field is null)
                throw new ArgumentException($"POB_COEF に存在しない係数名: 「{name}」");
            if (field.IsLiteral || field.IsInitOnly ||
                !(field.FieldType == typeof(double) || field.FieldType == typeof(int) || field.FieldType == typeof(bool)))
                throw new ArgumentException($"POB_COEF が扱えない係数: 「{name}」（{field.FieldType.Name}）");
            if (!double.TryParse(part[(eq + 1)..].Trim(), System.Globalization.NumberStyles.Float,
                                 System.Globalization.CultureInfo.InvariantCulture, out double v))
                throw new ArgumentException($"POB_COEF の値が数値でない: 「{part}」");
            if (field.FieldType == typeof(int) && !(double.IsFinite(v) && v >= int.MinValue && v <= int.MaxValue))
                throw new ArgumentException($"POB_COEF の値が int の範囲外/非数: 「{part}」");
            list.Add((name, v));
        }
        return [.. list];
    }

    public Coefficients()
    {
        foreach (var (name, value) in Overrides)
        {
            var f = typeof(Coefficients).GetField(name)!;
            if (f.FieldType == typeof(double)) f.SetValue(this, value);
            else if (f.FieldType == typeof(int)) f.SetValue(this, (int)value);
            else if (f.FieldType == typeof(bool)) f.SetValue(this, value > 0.5);
            else throw new ArgumentException($"POB_COEF が扱えない型の係数: 「{name}」（{f.FieldType.Name}）");
        }
    }

    /// <summary>この走行で上書きされた係数（測定の見出しに出して「掛けたつもり」を防ぐ）。</summary>
    public static string OverrideSummary()
        => Overrides.Length == 0 ? "" : string.Join(" ", Overrides.Select(o => $"{o.Name}={o.Value:G}"));
}
